[{"order":1,"type":"heading","text":"Component Lifecycle & Initialization in Svelte"},{"order":2,"type":"paragraph","text":"Svelte handles component lifecycles cleanly and efficiently by leveraging lifecycle functions imported directly from the 'svelte' module. Unlike traditional frameworks with heavy lifecycle methods, Svelte focuses on the reactive flow of the component from creation to destruction."},{"order":3,"type":"subheading","text":"Key Lifecycle Functions"},{"order":4,"type":"bullet_point","text":"onMount: Executes after the component is first rendered and inserted into the DOM."},{"order":5,"type":"bullet_point","text":"onDestroy: Executes just before the component is unmounted and removed from the DOM."},{"order":6,"type":"bullet_point","text":"beforeUpdate: Executes right before the DOM is updated due to state changes."},{"order":7,"type":"bullet_point","text":"afterUpdate: Executes immediately after the DOM has been updated."},{"order":8,"type":"subheading","text":"Implementation Example"},{"order":9,"type":"paragraph","text":"The following code demonstrates how to use onMount and onDestroy to handle data fetching and cleanup tasks, such as setting up timers or event listeners."},{"order":10,"type":"code","text":"<script>
  import { onMount, onDestroy } from 'svelte';

  let count = 0;
  let interval;

  onMount(() => {
    console.log('Component has mounted');
    interval = setInterval(() => {
      count += 1;
    }, 1000);

    return () => {
      // Optional cleanup returned directly from onMount
      console.log('Cleanup from onMount return function');
    };
  });

  onDestroy(() => {
    console.log('Component is about to be destroyed');
    clearInterval(interval);
  });
</script>

<div>
  <p>Timer count: {count}</p>
</div>"},{"order":11,"type":"subheading","text":"Tick Function"},{"order":12,"type":"paragraph","text":"Svelte also provides a tick() function. Unlike other lifecycle hooks, tick() can be called anywhere. It returns a promise that resolves as soon as any pending state changes have been applied to the DOM."},{"order":13,"type":"code","text":"<script>
  import { tick } from 'svelte';

  let text = 'Initial';

  async function updateText() {
    text = 'Updated';
    await tick();
    console.log('DOM is now fully updated with new text value');
  }
</script>

<button on:click="{updateText}">Update</button>
<p>{text}</p>"}]
